return [{ json: { html, filename, included, missing, notes, styleNotes: style.problems, palette: style.paletteName, usedAgentStyle: style.sheet.length > 0 || style.usedAgentColors, bytes: html.length } }];

// Makes the one page that the form shows at the end, whatever the outcome: the dossier (a Download button and a preview of the same file) or,
// when there is none, the reason. The form's own "return a file" ending downloads on page load with no click, which a browser may block while
// the page still says "downloaded"; a click on a link is a user action that is always allowed, and the preview shows the result on the spot.
// The file travels in the link as base64 and in the preview as an escaped attribute, so nothing that came from the web is read as markup
// here, and the preview is sandboxed: no script and no form, and its links open in a new tab.
const item = $input.first().json || {};
const html = typeof item.html === 'string' ? item.html : '';
if (!html) throw new Error('There is no page to show.');
// The reason that "Explain why there is no dossier" wrote is marked `notice`; everything else is a dossier.
if (item.notice === true) {
  const style = '<style>body{max-width:720px;margin:auto;font:16px/1.6 system-ui,sans-serif;padding:24px;color:#222;overflow-wrap:anywhere}.muted{color:#666;font-size:.9em}</style>';
  return [{ json: { page: style + html } }];
}
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const filename = String(item.filename || '').replace(/[^A-Za-z0-9._-]+/g, '-').slice(0, 80) || 'dossier.html';
const base64 = Buffer.from(html, 'utf8').toString('base64');
// A preview takes the address of the form page as its base, so a citation link (#s1) would load the form page again inside the preview
// instead of scrolling. In the preview copy only, the in-page links point at the preview itself; text from the web cannot contain
// the literal href="#s because its quotes are escaped.
const preview = html.replace(/href="#s/g, 'href="about:srcdoc#s');
const missing = Array.isArray(item.missing) && item.missing.length ? ' Missing this time: ' + item.missing.join(', ') + '.' : '';
const page = '<style>body{max-width:960px;margin:auto;font:16px/1.6 system-ui,sans-serif;padding:24px;color:#222;overflow-wrap:anywhere}'
  + 'h1{font-size:1.4rem;margin:0 0 12px}.bar{display:flex;flex-wrap:wrap;align-items:center;gap:14px;margin:0 0 16px}'
  + '.btn{display:inline-block;padding:10px 18px;background:#15803d;color:#fff;border-radius:6px;text-decoration:none;font-weight:600}'
  + '.muted{color:#666;font-size:.9em}iframe{display:block;width:100%;height:75vh;min-height:420px;border:1px solid #ccc;border-radius:6px;background:#fff}</style>'
  + '<h1>Your dossier is ready</h1>'
  + '<div class="bar"><a class="btn" download="' + esc(filename) + '" href="data:text/html;charset=utf-8;base64,' + base64 + '">Download ' + esc(filename) + '</a>'
  + '<span class="muted">One HTML file with no script; open it in any browser. To get a PDF, open the file and print it as PDF.' + esc(missing) + '</span></div>'
  + '<iframe title="Preview of the dossier" sandbox="allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer" srcdoc="' + esc(preview) + '"></iframe>';
return [{ json: { page, filename } }];

// The text of the page shown when there is no dossier: the request was not accepted, or too little could be found and verified.
// "Make the result page" adds the style, tells it from a dossier by `notice`, and ends the form.
const item = $input.first().json || {};
const esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
const reason = String(item.error || item.why || 'Nothing could be made.').replace(/\s+/g, ' ').slice(0, 400);
const html = '<h1>No dossier this time</h1><p>' + esc(reason) + '</p>'
  + '<p class="muted">The dossier is built only from pages that were read and quotes that were found in them, so a topic with too little to read gives no dossier. Nothing is made up to fill the gap.</p>';
return [{ json: { html, notice: true } }];
